public const string DailyBriefScript = "<script src=\"/assets/dashboard-daily-brief.js\"></script>";
    public const string ActivityTimelineScript = """
<script>fetch('/api/overview').then(r=>r.json()).then(o=>{const events=o.events||[];const card=document.createElement('div');card.className='col-12';card.innerHTML='<div class="card"><div class="card-header"><h2 class="card-title">Agent activity timeline</h2><div class="text-secondary small">Who acted, when, and which canonical record changed</div></div><div class="table-responsive"><table class="table table-vcenter"><thead><tr><th>When</th><th>Agent</th><th>Action</th><th>Record</th></tr></thead><tbody>'+(events.length?events.slice(0,20).map(e=>'<tr><td class="text-secondary small">'+new Date(e.occurredAtUtc).toLocaleString()+'</td><td><span class="badge bg-blue-lt">'+(e.actor||'repository')+'</span></td><td>'+e.type+'</td><td><code>'+e.entityId+'</code></td></tr>').join(''):'<tr><td colspan="4" class="text-secondary">No agent activity recorded yet.</td></tr>')+'</tbody></table></div></div>';document.querySelector('#records')?.before(card)}).catch(()=>{});</script>
""";
    public const string ProviderScript = """
<script>fetch('/api/llm/providers').then(r=>r.json()).then(items=>{const card=document.createElement('div');card.className='col-12';card.innerHTML='<div class="card"><div class="card-header"><h2 class="card-title">Provider health</h2><div class="text-secondary small">Connection tests run locally</div></div><div class="table-responsive"><table class="table table-vcenter"><thead><tr><th>Profile</th><th>Provider</th><th>Model</th><th>Runtime</th><th>Status</th><th></th></tr></thead><tbody>'+(items.length?items.map(x=>'<tr><td><code>'+x.id+'</code></td><td>'+x.provider+'</td><td>'+x.model+'</td><td>'+x.runtime+'</td><td id="health-'+x.id+'">'+(x.enabled?'Enabled':'Disabled')+'</td><td><button class="btn btn-sm" data-provider="'+x.id+'">Test connection</button></td></tr>').join(''):'<tr><td colspan="6" class="text-secondary">No provider profiles configured.</td></tr>')+'</tbody></table></div></div>';document.querySelector('#records')?.before(card);card.querySelectorAll('button[data-provider]').forEach(button=>button.onclick=async()=>{button.disabled=true;const id=button.dataset.provider;const response=await fetch('/api/llm/providers/'+encodeURIComponent(id)+'/test',{method:'POST'});const result=await response.json();const cell=card.querySelector('#health-'+CSS.escape(id));if(cell)cell.textContent=result.success?'Connected':'Failed: '+result.message;button.disabled=false})}).catch(()=>{});</script>
""";
    public const string ExecutiveSummaryScript = """
<script>fetch('/api/overview').then(r=>r.json()).then(o=>{const all=[...(o.decisions||[]),...(o.tasks||[]),...(o.claims||[]),...(o.evidence||[]),...(o.findings||[]),...(o.handoffs||[])];const latest=all.sort((a,b)=>new Date(b.createdAtUtc||0)-new Date(a.createdAtUtc||0))[0];const openTasks=(o.tasks||[]).filter(x=>(x.status||'').toUpperCase()==='OPEN').length;const openFindings=(o.findings||[]).filter(x=>(x.status||'').toUpperCase()==='OPEN').length;const llm=(o.llm||[]).length;const card=document.createElement('div');card.className='col-12';card.innerHTML='<div class="card border-primary"><div class="card-header"><h2 class="card-title">At a glance</h2><div class="text-secondary small">The shortest path to the current project decision</div></div><div class="card-body"><div class="row g-3"><div class="col-sm-6 col-lg-3"><div class="text-secondary small">Latest activity</div><strong>'+(latest?.summary||latest?.title||'No activity yet').slice(0,90)+'</strong></div><div class="col-sm-6 col-lg-3"><div class="text-secondary small">Open work</div><strong>'+openTasks+' task(s)</strong></div><div class="col-sm-6 col-lg-3"><div class="text-secondary small">Open risk</div><strong>'+openFindings+' finding(s)</strong></div><div class="col-sm-6 col-lg-3"><div class="text-secondary small">LLM runs</div><strong>'+llm+' recorded</strong></div></div><div class="mt-3 text-secondary small">Use the detailed cards below to inspect evidence, approvals, costs, and handoffs.</div></div></div>';document.querySelector('#overview')?.prepend(card)}).catch(()=>{});</script>
""";
    public const string LlmScript = """
<script>Promise.all([fetch('/api/overview').then(r=>r.json()),fetch('/api/llm/providers').then(r=>r.json())]).then(([o,providers])=>{const items=o.llmActivity||[];const tokens=items.reduce((s,x)=>s+(Number(x.tokens)||0),0);const cost=items.reduce((s,x)=>s+(Number(x.estimatedCost)||0),0);const card=document.createElement('div');card.className='col-12';card.innerHTML='<div class="card"><div class="card-header"><h2 class="card-title">LLM activity</h2><div class="text-secondary small">Provider, model, token and cost evidence · '+providers.length+' configured provider(s)</div></div><div class="card-body"><div class="row g-3 mb-3"><div class="col-md-3"><div class="text-secondary small">Runs</div><strong>'+items.length+'</strong></div><div class="col-md-3"><div class="text-secondary small">Total tokens</div><strong>'+tokens+'</strong></div><div class="col-md-3"><div class="text-secondary small">Estimated cost</div><strong>'+cost.toFixed(6)+'</strong></div><div class="col-md-3"><div class="text-secondary small">Enabled providers</div><strong>'+providers.filter(x=>x.enabled).length+'</strong></div></div><div class="table-responsive"><table class="table table-vcenter"><thead><tr><th>Evidence</th><th>Provider / model</th><th>Tokens</th><th>Cost</th><th>Created</th></tr></thead><tbody>'+(items.length?items.map(x=>'<tr><td><code>'+x.evidenceId+'</code></td><td>'+x.provider+' / '+x.model+'</td><td>'+x.tokens+'</td><td>'+x.estimatedCost+'</td><td>'+new Date(x.occurredAtUtc).toLocaleString()+'</td></tr>').join(''):'<tr><td colspan="5" class="text-secondary">No LLM activity recorded yet.</td></tr>')+'</tbody></table></div></div></div>';document.querySelector('#records')?.before(card)}).catch(()=>{});</script>
""";
    public const string DecisionBriefScript = """
<script>fetch('/api/overview').then(r=>r.json()).then(o=>{const all=[...o.decisions,...o.tasks,...o.claims,...o.evidence,...o.findings,...o.handoffs].map(x=>({...x,kind:x.kind||'record'}));const events=o.events||[];const latestEvent=events[0];const latest=all.sort((a,b)=>new Date(b.createdAtUtc||0)-new Date(a.createdAtUtc||0))[0];const agent=latest?.agent||latestEvent?.actor||'repository';const evidence=o.evidence||[];const newestEvidence=evidence.sort((a,b)=>new Date(b.createdAtUtc||0)-new Date(a.createdAtUtc||0))[0];const age=newestEvidence?.createdAtUtc?Math.floor((Date.now()-new Date(newestEvidence.createdAtUtc))/86400000):null;const freshness=age===null?'No evidence':age<=7?'Fresh':age<=30?'Aging':'Stale';const card=document.createElement('div');card.className='col-12';card.innerHTML='<div class="card"><div class="card-header"><h2 class="card-title">Decision-maker summary</h2><div class="text-secondary small">Who acted, what changed, and whether evidence is current</div></div><div class="card-body"><div class="row g-3 mb-3"><div class="col-md-4"><div class="text-secondary small">Latest agent</div><strong id="briefAgent"></strong></div><div class="col-md-4"><div class="text-secondary small">Latest action</div><strong id="briefAction"></strong></div><div class="col-md-4"><div class="text-secondary small">Evidence freshness</div><strong id="briefFreshness"></strong></div></div><div class="row g-2"><div class="col-md-4"><select class="form-select" id="briefKind"><option value="all">All record types</option><option value="decisions">Decisions</option><option value="tasks">Tasks</option><option value="claims">Claims</option><option value="evidence">Evidence</option><option value="findings">Findings</option><option value="handoffs">Handoffs</option></select></div><div class="col-md-4"><select class="form-select" id="briefStatus"><option value="all">All statuses</option><option>OPEN</option><option>COMPLETED</option><option>VERIFIED</option><option>ACCEPTED</option><option>REJECTED</option></select></div><div class="col-md-4"><select class="form-select" id="briefAgentFilter"><option value="all">All agents</option></select></div></div><div class="table-responsive mt-3"><table class="table table-vcenter"><thead><tr><th>Type</th><th>Record</th><th>Agent</th><th>Status</th><th>Evidence</th></tr></thead><tbody id="briefRows"></tbody></table></div></div></div>';document.querySelector('#records')?.before(card);const byKind={decisions:o.decisions,tasks:o.tasks,claims:o.claims,evidence:o.evidence,findings:o.findings,handoffs:o.handoffs};const rows=card.querySelector('#briefRows'),kind=card.querySelector('#briefKind'),status=card.querySelector('#briefStatus'),agentFilter=card.querySelector('#briefAgentFilter');const agents=[...new Set(all.map(x=>x.agent).filter(Boolean))];agents.forEach(a=>{const opt=document.createElement('option');opt.value=a;opt.textContent=a;agentFilter.appendChild(opt)});card.querySelector('#briefAgent').textContent=agent;card.querySelector('#briefAction').textContent=(latest?.title||latest?.statement||latest?.summary||latestEvent?.type||'No recent action').slice(0,120);card.querySelector('#briefFreshness').textContent=freshness+(age===null?'':' ('+age+'d)');function render(){const groups=kind.value==='all'?Object.entries(byKind):[[kind.value,byKind[kind.value]||[]]];rows.innerHTML=groups.flatMap(([k,items])=>items.filter(x=>(status.value==='all'||(x.status||'').toUpperCase()===status.value)&&(agentFilter.value==='all'||x.agent===agentFilter.value)).slice(0,20).map(x=>'<tr><td><span class="badge bg-blue-lt">'+k+'</span></td><td><strong>'+x.id+'</strong><div class="text-secondary small">'+(x.title||x.statement||x.summary||'').slice(0,100)+'</div></td><td>'+(x.agent||'repository')+'</td><td>'+(x.status||'—')+'</td><td>'+((x.claimId?evidence.filter(e=>e.claimId===x.claimId).length:0)||'—')+'</td></tr>').join('')||'<tr><td colspan="5" class="text-secondary">No records match the selected filters.</td></tr>'}kind.onchange=status.onchange=agentFilter.onchange=render;render()}).catch(()=>{});</script>
""";
    public const string ExtraScript = """
<script>fetch('/api/overview').then(r=>r.json()).then(o=>{const a=document.querySelector('#activity');if(a)a.innerHTML=o.events.map(e=>'<tr><td class="text-secondary small">'+new Date(e.occurredAtUtc).toLocaleString()+'</td><td><span class="badge bg-blue-lt">'+e.actor+'</span></td><td>'+e.type+'</td><td><code>'+e.entityId+'</code></td></tr>').join('');const card=document.createElement('div');card.className='col-12';card.innerHTML='<div class="card"><div class="card-header"><h2 class="card-title">Claims & evidence</h2><div class="text-secondary small">Verification freshness and support</div></div><div class="table-responsive"><table class="table table-vcenter"><thead><tr><th>Claim</th><th>Status</th><th>Evidence</th><th>Findings</th></tr></thead><tbody>'+o.claims.map(c=>'<tr><td><strong>'+c.id+'</strong><div class="text-secondary small">'+c.statement+'</div></td><td><span class="badge bg-green-lt">'+(c.status||'UNKNOWN')+'</span></td><td>'+o.evidence.filter(e=>e.claimId===c.id).length+' record(s)</td><td>'+o.findings.filter(f=>f.status==='OPEN').length+' open</td></tr>').join('')+'</tbody></table></div></div>';document.querySelector('#records')?.before(card)}).catch(()=>{});</script>
""";
    public const string WorkScript = """
<script>fetch('/api/overview').then(r=>r.json()).then(o=>{const card=document.createElement('div');card.className='col-12';const tasks=o.tasks.filter(x=>x.status==='OPEN');const findings=o.findings.filter(x=>x.status==='OPEN');card.innerHTML='<div class="row row-cards"><div class="col-lg-6"><div class="card h-100"><div class="card-header"><h2 class="card-title">Work board</h2><span class="badge bg-blue-lt">'+tasks.length+' open</span></div><div class="list-group list-group-flush">'+(tasks.length?tasks.map(t=>'<div class="list-group-item"><div class="d-flex justify-content-between"><strong>'+t.id+'</strong><span class="badge bg-yellow-lt">'+(t.status||'OPEN')+'</span></div><div>'+t.title+'</div><div class="text-secondary small">Risk: '+(t.risk||'unclassified')+'</div></div>').join(''):'<div class="list-group-item text-secondary">No open tasks.</div>')+'</div></div></div><div class="col-lg-6"><div class="card h-100"><div class="card-header"><h2 class="card-title">Findings & risk</h2><span class="badge bg-red-lt">'+findings.length+' open</span></div><div class="list-group list-group-flush">'+(findings.length?findings.map(f=>'<div class="list-group-item"><div class="d-flex justify-content-between"><strong>'+f.id+'</strong><span class="badge bg-red-lt">'+(f.severity||'UNKNOWN')+'</span></div><div>'+f.title+'</div><div class="text-secondary small">'+f.summary+'</div></div>').join(''):'<div class="list-group-item text-secondary">No open findings.</div>')+'</div></div></div></div>';document.querySelector('#records')?.before(card)}).catch(()=>{});</script>
""";
    public const string HandoffScript = """
